\begin{corollary}
\label{topping-maxpr-positive-scalar-preserved}
\source{topping:page-0047}
\dcref{ch3:2.3}
\group{maximum-principle}

Under Ricci flow on a closed manifold, positive and weakly positive scalar
curvature are preserved.
\end{corollary}

